const SUPABASE_CONFIG = {
  // Live Supabase Project URL
  url: window.__SUPABASE_URL || 'https://pmpwrvbceudajdkkdvfs.supabase.co',
  // Live Supabase Publishable / Anon API Key
  anonKey: window.__SUPABASE_ANON_KEY || 'sb_publishable_35vybrSitrOX8XhqnvPd6w_DjSgftva'
};

let supabaseClient = null;

// Initialize Supabase Client if library is loaded
function initSupabase() {
  if (window.supabase && typeof window.supabase.createClient === 'function') {
    try {
      const cleanUrl = (SUPABASE_CONFIG.url || '').replace(/\/rest\/v1\/?$/, '');
      if (cleanUrl && SUPABASE_CONFIG.anonKey) {
        supabaseClient = window.supabase.createClient(cleanUrl, SUPABASE_CONFIG.anonKey);
        console.log('✅ Supabase Client initialized with live project:', cleanUrl);
      }
    } catch (err) {
      console.warn('⚠️ Supabase initialization warning:', err.message);
    }
  }
}

/**
 * Save devotee booking and UPI payment details
 * @param {Object} donationData 
 * @returns {Promise<Object>}
 */
async function saveDevoteeDonation(donationData) {
  const record = {
    devotee_name: donationData.name || 'Anonymous Devotee',
    devotee_phone: donationData.phone || '',
    devotee_gothram: donationData.gothram || '',
    devotee_nakshatram: donationData.nakshatram || '',
    devotee_address: donationData.address || '',
    seva_name: donationData.sevaName || 'Veda Parayana Seva',
    gopuram_selection: donationData.gopurams || '',
    amount: parseFloat(donationData.amount) || 0,
    upi_reference: donationData.upiRef || '',
    payment_status: 'COMPLETED',
    payment_method: 'UPI',
    receipt_number: donationData.receiptNo || 'SKYVPT-' + Math.floor(100000 + Math.random() * 900000),
    created_at: new Date().toISOString()
  };

  // Always save to LocalStorage as resilient backup
  try {
    const existing = JSON.parse(localStorage.getItem('skyvpt_donations') || '[]');
    existing.unshift(record);
    localStorage.setItem('skyvpt_donations', JSON.stringify(existing));
    console.log('💾 Record saved to local backup cache:', record);
  } catch (e) {
    console.warn('LocalStorage error:', e);
  }

  // Attempt save to Supabase if connected
  if (supabaseClient) {
    try {
      const { data, error } = await supabaseClient
        .from('devotee_donations')
        .insert([record])
        .select();

      if (error) {
        console.error('Supabase insert error:', error);
        return { success: false, fallback: true, error: error.message, record };
      }
      console.log('✅ Successfully recorded donation in Supabase:', data);
      return { success: true, data, record };
    } catch (err) {
      console.error('Supabase exception:', err);
      return { success: false, fallback: true, error: err.message, record };
    }
  }

  return { success: true, fallback: true, record };
}

/**
 * Fetch all devotee bookings and donations from Supabase or LocalStorage
 * @returns {Promise<Array>}
 */
async function getDevoteeDonations() {
  if (supabaseClient) {
    try {
      const { data, error } = await supabaseClient
        .from('devotee_donations')
        .select('*')
        .order('created_at', { ascending: false });

      if (!error && Array.isArray(data) && data.length > 0) {
        return data;
      }
    } catch (err) {
      console.warn('Supabase fetch error, falling back to local storage:', err);
    }
  }

  // Fallback to local storage
  try {
    return JSON.parse(localStorage.getItem('skyvpt_donations') || '[]');
  } catch (e) {
    return [];
  }
}

// Auto-run initialization on load
if (typeof window !== 'undefined') {
  window.saveDevoteeDonation = saveDevoteeDonation;
  window.getDevoteeDonations = getDevoteeDonations;
  window.initSupabase = initSupabase;
  window.addEventListener('DOMContentLoaded', initSupabase);
}

